import pathlib,json,urllib.request,urllib.error
cfg=json.loads(pathlib.Path('/home/appontrack/ontrack-voice-link/config.json').read_text())
url='https://api.github.com/repos/OnTrack-Development/OnTrack-voice/contents/ayo/index.php?ref=feat/ayo-php-host-demo-20261105'
h={'Authorization':'Bearer '+cfg['token'],'Accept':'application/vnd.github+json','User-Agent':'OnTrack-AYO-ReadOnly-Probe'}
try:
 with urllib.request.urlopen(urllib.request.Request(url,headers=h),timeout=10) as r:
  data=json.load(r)
 print(json.dumps({'api_http':200,'file':'ayo/index.php','sha':data.get('sha'),'has_content':bool(data.get('content'))}))
except urllib.error.HTTPError as e:print(json.dumps({'api_http':e.code,'error_class':'token_repo_access'}))
